new file mode 100644
index 0000000..e0dbe28
--- /dev/null
+++ b/test/tmp_uoge.js
@@ -0,0 +1,79 @@
+'use strict';
+
+const assert = require('assert');
+const db = require('./mocks/databasemock');
+const User = require('../src/user');
+const Groups = require('../src/groups');
+const meta = require('../src/meta');
+
+describe('tmp userOrGroupExists array support', () => {
+	before(async function () {
+		this.timeout(30000);
+		await User.create({ username: 'John Smith', password: 'swordfish' });
+		await Groups.create({ name: 'registered-users' }).catch(() => {});
+	});
+
+	it('single group slug -> true', async () => {
+		assert.strictEqual(await meta.userOrGroupExists('registered-users'), true);
+	});
+
+	it('single user slug -> true', async () => {
+		assert.strictEqual(await meta.userOrGroupExists('John Smith'), true);
+		assert.strictEqual(await meta.userOrGroupExists('john smith'), true);
+		assert.strictEqual(await meta.userOrGroupExists('JOHN SMITH'), true);
+	});
+
+	it('non-existing slug -> false', async () => {
+		assert.strictEqual(await meta.userOrGroupExists('doesnot exist'), false);
+	});
+
+	it('array of non-existing -> [false, false]', async () => {
+		assert.deepStrictEqual(await meta.userOrGroupExists(['doesnot exist', 'nope not here']), [false, false]);
+	});
+
+	it('mixed array (user + non-existing) -> [false, true]', async () => {
+		assert.deepStrictEqual(await meta.userOrGroupExists(['doesnot exist', 'John Smith']), [false, true]);
+	});
+
+	it('mixed array (group + user) -> [true, true]', async () => {
+		assert.deepStrictEqual(await meta.userOrGroupExists(['administrators', 'John Smith']), [true, true]);
+	});
+
+	it('invalid array input rejects', async () => {
+		await assert.rejects(meta.userOrGroupExists(['', undefined]), (err) => err.message === '[[error:invalid-data]]');
+		await assert.rejects(meta.userOrGroupExists(['John Smith', null]), (err) => err.message === '[[error:invalid-data]]');
+	});
+
+	it('invalid single input rejects', async () => {
+		await assert.rejects(meta.userOrGroupExists(null), (err) => err.message === '[[error:invalid-data]]');
+		await assert.rejects(meta.userOrGroupExists(''), (err) => err.message === '[[error:invalid-data]]');
+		await assert.rejects(meta.userOrGroupExists(undefined), (err) => err.message === '[[error:invalid-data]]');
+	});
+
+	it('duplicates map positionally', async () => {
+		assert.deepStrictEqual(await meta.userOrGroupExists(['john smith', 'John Smith', 'john smith']), [true, true, true]);
+	});
+
+	it('getUidsByUserslugs preserves order and returns nulls for missing', async () => {
+		const uid = await User.getUidByUserslug('john-smith');
+		assert.ok(uid > 0);
+		const uids = await User.getUidsByUserslugs(['john-smith', 'nope-not-here', 'john-smith']);
+		assert.deepStrictEqual(uids, [uid, null, uid]);
+		assert.deepStrictEqual(await User.getUidsByUserslugs([]), []);
+	});
+
+	it('callback interface still works', (done) => {
+		meta.userOrGroupExists('registered-users', (err, exists) => {
+			assert.ifError(err);
+			assert.strictEqual(exists, true);
+			meta.userOrGroupExists(['doesnot exist', 'John Smith'], (err2, exists2) => {
+				assert.ifError(err2);
+				assert.deepStrictEqual(exists2, [false, true]);
+				meta.userOrGroupExists(null, (err3) => {
+					assert.strictEqual(err3.message, '[[error:invalid-data]]');
+					done();
+				});
+			});
+		});
+	});
+});
