+++ b/test/tmp_userOrGroup.js
@@ -0,0 +1,72 @@
+'use strict';
+
+const assert = require('assert');
+
+const db = require('./mocks/databasemock');
+const meta = require('../src/meta');
+const groups = require('../src/groups');
+const User = require('../src/user');
+
+describe('meta.userOrGroupExists array support (tmp)', () => {
+	before(async function () {
+		this.timeout(60000);
+		await User.create({ username: 'John Smith', password: 'swordfish' });
+		await groups.create({ name: 'mygroup' });
+		await groups.join('administrators', 1);
+	});
+
+	it('single group slug', async () => {
+		assert.strictEqual(await meta.userOrGroupExists('registered-users'), true);
+	});
+
+	it('single user slug', async () => {
+		assert.strictEqual(await meta.userOrGroupExists('John Smith'), true);
+	});
+
+	it('non-existing slug', async () => {
+		assert.strictEqual(await meta.userOrGroupExists('doesnot exist'), false);
+	});
+
+	it('array of non-existing slugs', async () => {
+		assert.deepStrictEqual(await meta.userOrGroupExists(['doesnot exist', 'nope not here']), [false, false]);
+	});
+
+	it('mixed array (non-existing + user)', async () => {
+		assert.deepStrictEqual(await meta.userOrGroupExists(['doesnot exist', 'John Smith']), [false, true]);
+	});
+
+	it('mixed array (group + user)', async () => {
+		assert.deepStrictEqual(await meta.userOrGroupExists(['administrators', 'John Smith']), [true, true]);
+	});
+
+	it('rejects array with falsy elements', async () => {
+		await assert.rejects(
+			meta.userOrGroupExists(['', undefined]),
+			(err) => err.message === '[[error:invalid-data]]'
+		);
+	});
+
+	it('rejects falsy single input', async () => {
+		await assert.rejects(
+			meta.userOrGroupExists(null),
+			(err) => err.message === '[[error:invalid-data]]'
+		);
+	});
+
+	it('preserves order and duplicates', async () => {
+		assert.deepStrictEqual(
+			await meta.userOrGroupExists(['john smith', 'JOHN SMITH', 'registered-users', 'john smith']),
+			[true, true, true, true]
+		);
+		assert.deepStrictEqual(
+			await meta.userOrGroupExists(['nope not here', 'mygroup', 'nope not here']),
+			[false, true, false]
+		);
+	});
+
+	it('User.getUidsByUserslugs returns uids in order', async () => {
+		const uid = await User.getUidByUsername('John Smith');
+		assert.deepStrictEqual(await User.getUidsByUserslugs(['john-smith', 'doesnot-exist']), [uid, null]);
+		assert.deepStrictEqual(await User.getUidsByUserslugs(['john-smith', 'john-smith']), [uid, uid]);
+	});
+});

