 /* Assorted */
 Meta.userOrGroupExists = async function (slug) {
+	const user = require('../user');
+	const groups = require('../groups');
+	const isArray = Array.isArray(slug);
+	if (isArray) {
+		if (slug.some(s => !s)) {
+			throw new Error('[[error:invalid-data]]');
+		}
+		const slugs = slug.map(s => slugify(s));
+		const [uids, groupSlugsExist] = await Promise.all([
+			user.getUidsByUserslugs(slugs),
+			groups.existsBySlug(slugs),
+		]);
+		return slugs.map((s, i) => !!uids[i] || !!groupSlugsExist[i]);
+	}
 	if (!slug) {
 		throw new Error('[[error:invalid-data]]');
 	}
-	const user = require('../user');
-	const groups = require('../groups');
-	slug = slugify(slug);
+	const normalizedSlug = slugify(slug);
 	const [userExists, groupExists] = await Promise.all([
-		user.existsBySlug(slug),
-		groups.existsBySlug(slug),
+		user.existsBySlug(normalizedSlug),
+		groups.existsBySlug(normalizedSlug),
 	]);
 	return userExists || groupExists;
 };
